# Probe: does append work when the field value is a list but the doc is frozen?
from tinydb import TinyDB, Query
from tinydb.storages import MemoryStorage
from tinydb.operations import append
import tinydb.utils as u

# frozen doc
try:
    append('tags', 1)(u.freeze({'tags': []}))
except Exception as e:
    print("frozen:", type(e).__name__, e)

# field present with value None
d = {'tags': None}
try:
    append('tags', 1)(d)
except Exception as e:
    print("None field:", type(e).__name__, e)

# field present with bool
d = {'tags': True}
try:
    append('tags', 1)(d)
except Exception as e:
    print("bool field:", type(e).__name__, e)

# field present with dict
d = {'tags': {}}
try:
    append('tags', 1)(d)
except Exception as e:
    print("dict field:", type(e).__name__, e)
EOF
